import {DECAL_NAMES,MAX_BUILDING_DECALS,anchoredDecal,decalPolygonsOnFace} from './building-decals.js?v=architecture-collection-44';
import {projectedBuildingSurfaces,pickBuildingSurface,pointInBuildingSurface} from './building-surface-picking.js?v=architecture-collection-44';
import {buildingPropPickFaces,pickBuildingProp} from './building-prop-picking.js?v=architecture-collection-44';
import {projectBuildingPoint} from './building-footprints.js?v=architecture-collection-44';
export const anchoredDetailMode=mode=>['anchored-detail','sample-decal','erase-decal'].includes(mode);
export function mountBuildingDecalEditor(root,canvas,{get,camera,mode,material,apply,render,status}){
 root.innerHTML=`<fieldset id="anchoredDetailControls"><legend>Anchored wall details</legend><div class="block-editor-controls"><label>Detail design<select id="decalKind">${DECAL_NAMES.slice(1).map((name,i)=>`<option value="${i+1}">${name}</option>`).join('')}</select></label><label>Width (wall tiles)<input id="decalWidth" type="number" min=".25" max="10" step=".25" value="2"></label><label>Height (floors)<input id="decalHeight" type="number" min=".25" max="25" step=".25" value="2"></label></div><p class="fine">The highlighted wall tile anchors the lower-left corner. Details extend right and up, clipping at wall edges, gaps and slopes. Click and release to place; Shift or Escape cancels. Select an anchored detail to reuse its design and size. Erase removes the selected placement; Undo restores it.</p></fieldset>`;
 const $=id=>root.querySelector('#'+id),kind=$('decalKind'),width=$('decalWidth'),height=$('decalHeight'),controls=$('anchoredDetailControls');
 const base=Object.fromEntries(['onpointerdown','onpointermove','onpointerup','onpointercancel','onkeydown','onwheel'].map(k=>[k,canvas[k]]));let hover=null,pending=null,cache=null;
 const active=()=>anchoredDetailMode(mode.value),point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
 function geometry(){const d=get(),key=[d.blocks,d.voxels,d.blockGeometry,d.footprint,d.props,d.rotation];if(!cache||key.some((v,i)=>v!==cache.key[i]))cache={key,faces:projectedBuildingSurfaces(d,d.rotation),props:buildingPropPickFaces(d,d.rotation)};return cache;}
 function pick(p){if(!p)return null;const f=geometry();if(pickBuildingProp(f.props,p,camera())!==null)return null;const face=pickBuildingSurface(f.faces,p,camera());return face?.side!==4?face:null;}
 function owner(face,p){if(!face)return null;const d=get(),c=camera(),local={x:(p.x-c.x)/c.zoom,y:(p.y-c.y)/c.zoom},polygons=decalPolygonsOnFace(face,d.decals,d);for(let i=polygons.length-1;i>=0;i--)if(pointInBuildingSurface(local,polygons[i].points.map(p=>projectBuildingPoint(p,d.rotation,d.footprint))))return polygons[i].owner;return null;}
 const signature=()=>JSON.stringify([get().blocks,get().voxels,get().blockGeometry,get().decals,get().props,get().footprint,get().rotation,camera()]);
 function placement(face){if(!face)return null;try{return anchoredDecal(face,Number(kind.value),Number(width.value),Math.round(Number(height.value)*140)/1000);}catch(error){status.textContent=error.message;return null;}}
 function describe(face){if(!face){status.textContent='Point at a visible wall on a block or layered building.';return;}status.textContent=mode.value==='anchored-detail'?`Lower-left anchor · wall tile ${face.x+1}, ${face.y+1}. Width ${width.value} tiles · height ${height.value} floors.`:'Point at the visible part of an anchored detail to select or erase it.';}
 function sample(face){const index=owner(face,hover),d=index===null?null:get().decals[index];if(!d){status.textContent='No anchored detail here. Your selection is unchanged.';return;}kind.value=String(d.kind);width.value=String(d.width);height.value=String(Math.round(d.height/.14*1000)/1000);status.textContent=`Selected ${DECAL_NAMES[d.kind]}. The building is unchanged.`;}
 function commit(action){if(action.kind==='place'){const list=get().decals||[];if(list.length>=MAX_BUILDING_DECALS){status.textContent='Remove an anchored detail before adding another (32 maximum).';return;}apply([...list,action.detail]);}else if(action.index!==null)apply(get().decals.filter((_,i)=>i!==action.index));}
 function action(face){return mode.value==='anchored-detail'?{kind:'place',detail:placement(face)}:{kind:'erase',index:owner(face,hover)};}
 const previousMode=mode.onchange;mode.onchange=()=>{pending=null;hover=null;previousMode?.();refresh();if(active()){material.disabled=true;describe(null);render();}};
 for(const control of [kind,width,height])control.onchange=control.oninput=()=>{pending=null;render();};
 function refresh(){controls.hidden=!active();for(const c of [kind,width,height])c.disabled=mode.value!=='anchored-detail';}
 canvas.onpointerdown=e=>{if(!active())return base.onpointerdown?.(e);if(e.button!==0)return;e.preventDefault();canvas.focus({preventScroll:true});hover=point(e);const face=pick(hover);if(mode.value==='sample-decal')sample(face);else{const next=action(face);pending=next.kind==='place'&&!next.detail?null:{id:e.pointerId,signature:signature(),...next};if(pending)canvas.setPointerCapture(e.pointerId);}render();};
 canvas.onpointermove=e=>{if(!active())return base.onpointermove?.(e);hover=point(e);describe(pick(hover));render();};
 canvas.onpointerup=e=>{if(!active())return base.onpointerup?.(e);if(pending?.id!==e.pointerId)return;const action=pending;pending=null;if(!e.shiftKey&&action.signature===signature())commit(action);render();};
 canvas.onpointercancel=e=>{if(!active())return base.onpointercancel?.(e);pending=null;render();};canvas.onwheel=e=>{pending=null;base.onwheel?.(e);};
 canvas.onkeydown=e=>{if(!active())return base.onkeydown?.(e);if(e.key==='Escape'){pending=null;e.preventDefault();e.stopPropagation();render();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();e.stopPropagation();pending=null;hover??={x:128,y:320};const step=e.shiftKey?24:8;if(e.key==='ArrowLeft')hover.x-=step;if(e.key==='ArrowRight')hover.x+=step;if(e.key==='ArrowUp')hover.y-=step;if(e.key==='ArrowDown')hover.y+=step;const face=pick(hover);if(e.key==='Enter'){if(mode.value==='sample-decal')sample(face);else{const next=action(face);if(next.kind!=='place'||next.detail)commit(next);}}else describe(face);render();return;}pending=null;base.onkeydown?.(e);};
 refresh();return{refresh,reset(){pending=null;hover=null;cache=null;refresh();},draw(ctx){if(!active())return;const face=pick(hover);if(!face)return;ctx.save();ctx.strokeStyle='#ffe180';ctx.lineWidth=1.2/camera().zoom;ctx.beginPath();face.polygon.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();ctx.restore();}};
}
